                horn1.rotation.set(0.3, 0.4, 0.5);
                bodyGroup.add(horn1);
                const horn2 = new THREE.Mesh(new THREE.TorusGeometry(0.22, 0.07, 4, 6, Math.PI), secondaryMat);
                horn2.position.set(0.3, 1.0, 0);
