                const torso = new THREE.Mesh(new THREE.BoxGeometry(0.75, 1.3, 0.45), primaryMat);
                torso.castShadow = true;
                bodyGroup.add(torso);

                const helm = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.26, 0.45, 8), primaryMat);
                helm.position.y = 0.88;
                bodyGroup.add(helm);

                // Arms
                const rArm = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.9, 0.2), secondaryMat);
                rArm.position.set(0.5, 0.15, 0);
                bodyGroup.add(rArm);
                const lArm = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.9, 0.2), secondaryMat);
                lArm.position.set(-0.5, 0.15, 0);
                bodyGroup.add(lArm);

                // Legs
                const rLeg = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.9, 0.22), secondaryMat);
                rLeg.position.set(0.22, -0.9, 0);
