                const lLeg = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.9, 0.22), secondaryMat);
                lLeg.position.set(-0.22, -0.9, 0);
                bodyGroup.add(lLeg);

                // Weapon
                const sword = new THREE.Mesh(new THREE.BoxGeometry(0.12, 1.8, 0.04), this.steelMat);
                sword.position.set(0.6, 0.3, 0.5);
